/**
 * Levelling coach (Stage 7): an act-by-act plan and the next steps for a levelling
 * character, from the guide's levelling stages (Stage 3) or from the open build.
 *
 * The engine is PoB-side (PathOfBuilding/src/Agent/Handlers/Levelling.lua): every
 * number comes from PoB, every game fact from Agent/LevellingData.lua (generated by
 * scripts/levelling-data.mjs from poewiki, each fact with its link and a quote).
 * The guide build is read in the side engine, never in the player's window.
 */
import fs from "fs";
import path from "path";
import { readState } from "./guideMode.js";
import { ToolError, type Pob } from "./pob.js";
import { buildFile, currentBuildsDir } from "./tools/session.js";

export interface LevellingArgs {
  /** Guide build name ("Guide - X" or X); default: the guide picked for this build, else none. */
  guide?: string;
  /** Act-by-act plan (default: only where the character stands and what is next). */
  plan?: boolean;
  level?: number;
  act?: number;
}

const actName = (a: number) => (a >= 11 ? "maps" : `Act ${a}`);
const pct = (v: unknown) => `${Math.round(Number(v) || 0)}%`;
const signed = (v: number, unit = "") => `${v >= 0 ? "+" : ""}${Math.round(v * 10) / 10}${unit}`;

/** The guide build file for the open build: asked for, else the one picked for it in guide mode. */
function guideFile(dir: string, player: string, wanted?: string): string | undefined {
  if (wanted && wanted.trim()) {
    for (const name of [wanted.trim().replace(/\.xml$/i, ""), `Guide - ${wanted.trim().replace(/\.xml$/i, "")}`]) {
      const file = buildFile(dir, name);
      if (fs.existsSync(file)) return file;
    }
    throw new ToolError(`No guide "${wanted}" in ${dir}. Import one first (guide_import), or leave guide out to plan from the build itself.`);
  }
  const choice = readState().builds[player];
  if (choice?.guide) {
    const file = buildFile(dir, choice.guide);
    if (fs.existsSync(file)) return file;
  }
  return undefined;
}

const guideCache = new Map<string, any>();

/** The guide's stages in levelling order, read in the side engine (cached per file version). */
async function guideStages(pob: Pob, file: string): Promise<any> {
  const key = `${file}|${fs.statSync(file).mtimeMs}`;
  let stages = guideCache.get(key);
  if (!stages) {
    const side = await pob.sideLink();
    await side.call("load_build_xml", { xml: fs.readFileSync(file, "utf8"), name: path.basename(file, ".xml") });
    stages = await side.call("levelling_guide_stages", {});
    guideCache.set(key, stages);
  }
  return stages;
}

export async function levellingPlan(pob: Pob, args: LevellingArgs): Promise<any> {
  const link = await pob.link();
  const me = await link.call("key_stats", {});
  const dir = await currentBuildsDir(pob);
  const file = guideFile(dir, String(me.name ?? ""), args.guide);
  const guide = file ? await guideStages(pob, file) : undefined;
  const params: Record<string, unknown> = { guide, simulate: !!args.plan };
  if (args.level) params.level = args.level;
  if (args.act) params.act = args.act;
  return link.call(args.plan ? "levelling_plan" : "levelling_next", params, 120_000);
}

function whereLine(p: any): string {
  const me = p.me;
  const actFrom = me.actFrom === "pob" ? "PoB's estimate from your passive points" : me.actFrom === "given" ? "as given" : "from your level";
  const from = p.from === "guide" ? `following ${String(p.guideName).replace(/^Guide - /, "")}${p.stageNow ? `, stage "${p.stageNow.title}"` : ""}` : "no guide picked: planned from this build";
  return `LEVELLING: ${me.className}${me.ascendancy ? ` (${me.ascendancy})` : ""} level ${me.level}, ${actName(me.act)} (${actFrom}); ${me.points} passive points, ${me.ascPoints} ascendancy points; ${from}.`;
}

function resistLines(r: any): string[] {
  if (!r?.elements?.length) return [];
  const now = r.elements.map((e: any) => `${e.name} ${pct(e.now)}`).join(", ");
  const L = [`Resistances now: ${now} (PoB${r.configNote ? `; ${r.configNote}` : ""}).`];
  if (r.nextAfterAct) {
    const after = r.elements.map((e: any) => `${e.name} ${pct(e.after)}${e.missingAfter > 0 ? ` (+${Math.round(e.missingAfter)} to cap)` : ""}`).join(", ");
    L.push(`After finishing Act ${r.nextAfterAct} (${r.nextPenalty}% to all resistances): ${after}.`);
  }
  return L;
}

function sourceLine(p: any): string {
  const d = p.data ?? {};
  return `Facts: poewiki.net (CC BY-NC-SA 3.0), read ${d.generated}, for game ${d.gameVersion}; ${d.patchCheck ?? ""} Numbers: PoB, your config.`;
}

/** The short answer: where the character stands and the next steps. */
export function nextText(p: any): string {
  const L = [whereLine(p), ...resistLines(p.resists ?? p.checkpoints?.resists), "NEXT:"];
  for (const [i, s] of (p.next ?? []).entries()) L.push(`${i + 1}. [${s.kind}] ${s.text}`);
  if (!(p.next ?? []).length) L.push("Nothing urgent for this level.");
  const nextLab = (p.labs ?? p.milestones?.labs ?? []).find((l: any) => l.status === "next");
  if (nextLab) L.push(`Labs done: ${(p.labs ?? p.milestones?.labs).filter((l: any) => l.status === "done").length}/4 (2 ascendancy points each). Next: ${nextLab.name} (monster level ${nextLab.monsterLevel}).`);
  L.push(sourceLine(p));
  return L.join("\n");
}

/** The full act-by-act plan. */
export function planText(p: any): string {
  const L = [whereLine(p), ...resistLines(p.checkpoints?.resists), ""];
  L.push(p.from === "guide" ? `STAGES (guide, by points): ${p.stages.map((s: any) => `${s.title} ~level ${s.level}${s.levelFrom === "points" ? " (from its points)" : ""}`).join(" | ")}` : "PLAN FROM THIS BUILD (its tree, gems and ascendancy, in walking order).");
  L.push("", "ACT BY ACT (levels = campaign area levels)");
  for (const a of p.acts ?? []) {
    const head = `${actName(a.act)} (levels ${a.levels[0]}-${a.levels[1]})`;
    const parts: string[] = [];
    if (a.questPoints.length) parts.push(`passive point quests: ${a.questPoints.join(", ")}`);
    if (a.trials.length) parts.push(`lab trials: ${a.trials.join(", ")}`);
    const named = a.passives.map((x: any) => `${x.name} (~${x.level})`);
    if (named.length || a.small) parts.push(`passives: ${named.join(", ")}${a.small ? `${named.length ? " + " : ""}${a.small} small` : ""}`);
    for (const s of a.swaps) parts.push(`SWAP main skill ${s.from} -> ${s.to} at level ${s.level}`);
    for (const l of a.links) parts.push(`${l.skill} ${l.links}-link${l.supports?.length ? ` (${l.supports.join(", ")})` : ""}`);
    const gems = a.gems.map((g: any) => `${g.name}${g.req > 1 ? ` (lvl ${g.req})` : ""}: ${g.text.replace(/^Act \d+ /, "").replace(/^: /, "")}`);
    if (gems.length) parts.push(`gems: ${gems.join("; ")}`);
    for (const n of a.notes) parts.push(n);
    if (parts.length) L.push(`- ${head}: ${parts.join(". ")}.`);
  }
  const m = p.milestones ?? {};
  L.push("", "MILESTONES");
  for (const lab of m.labs ?? []) {
    const when = lab.maps ? `level ${lab.minLevel}+, maps (Offering to the Goddess)` : `after its trials (Acts ${lab.trials[0]?.act}-${lab.afterAct})${lab.minLevel ? `, level ${lab.minLevel}+` : ""}`;
    L.push(`- ${lab.name} Labyrinth (monster level ${lab.monsterLevel}): ${lab.status}${lab.ready ? ", open to you now" : ""}; ${when}${lab.nodes.length ? `; take ${lab.nodes.join(", ")}` : ""}.`);
  }
  if (m.labFacts) L.push(`  "${m.labFacts.points}" "${m.labFacts.shared}" (${m.labFacts.source?.url})`);
  const b = m.bandit;
  if (b) {
    const opts = b.options.map((o: any) => {
      const g = o.gain;
      const sim = g ? ` -> PoB: DPS ${signed(g.dpsPct, "%")}, EHP ${signed(g.ehp)}, life ${signed(g.life)}, fire/cold/lightning ${signed(g.fire)}/${signed(g.cold)}/${signed(g.lightning)}, move ${signed(g.ms, "%")}` : "";
      return `${o.choice}: ${o.reward}${sim}`;
    });
    L.push(`- Bandit (Act ${b.act}): now "${b.current === "None" ? "kill all" : b.current}"${b.guide ? `, guide "${b.guide === "None" ? "kill all" : b.guide}"` : ""}. ${opts.join("; ")}. To change later: "${b.change}" (${b.source?.url}).`);
  }
  const pan = m.pantheon;
  if (pan) {
    const gods = pan.gods.map((g: any) => `${g.name} (${g.major ? "major" : "minor"}, Act ${g.act}${g.unlocked ? ", unlocked" : ""})`).join(", ");
    L.push(`- Pantheon (from Act ${pan.firstAct}): "${pan.swap}" Now: major ${pan.current.major}, minor ${pan.current.minor}${pan.guide ? `; guide: major ${pan.guide.major ?? "-"}, minor ${pan.guide.minor ?? "-"}` : ""}. Gods: ${gods}. (${pan.source?.url})`);
  }
  const q = p.questPoints;
  if (q) L.push(`- Quest passive points: ${q.total} in the campaign ("${q.quote}"); your tree has ${q.allocated}, level ${p.me.level} with the quests before ${actName(p.me.act)} gives at least ${q.expectedAtLeast}${q.unspentOrMissed ? ` -> ${q.unspentOrMissed} unspent or missed (in game: /passives)` : ""}.`);
  const g = p.checkpoints?.gear ?? {};
  L.push("", "GEAR CHECKPOINTS");
  if (g.links) L.push(`- Links: ${g.links.skill} has ${g.links.gems} gems; ${g.links.item ?? "no item"} in ${g.links.slot ?? "?"} has a ${g.links.links}-link (${g.links.sockets} sockets)${g.links.target ? `; the plan uses ${g.links.target}` : ""}. Sockets by item level: ${g.links.sockets4.map((s: any) => `${s.sockets} from ilvl ${s.ilvl} (vendors from Act ${s.vendorAct})`).join(", ")}; "${g.links.max4}". Chromatic recipe: ${g.links.chromatic?.inputs?.join(" + ")}.`);
  if (g.boots) L.push(`- Boots: ${g.boots.item ?? "none"}${g.boots.movementSpeed ? " (has movement speed)" : " WITHOUT movement speed"}. Recipe: ${g.boots.recipe.inputs.join(" + ")} = ${g.boots.recipe.result}. Kraityn (bandit) also gives movement speed.`);
  if (g.weapon) L.push(`- Weapon (${g.weapon.kind} skill, ${g.weapon.item ?? "none"}): recipes ${g.weapon.recipes.map((r: any) => `${r.inputs.join(" + ")} = ${r.result}`).join("; ")}.`);
  L.push("", "NEXT:");
  for (const [i, s] of (p.next ?? []).entries()) L.push(`${i + 1}. [${s.kind}] ${s.text}`);
  L.push("", sourceLine(p));
  const outdated = Object.values(p.data?.sources ?? {}).filter((s: any) => s?.outdated);
  if (outdated.length) L.push(`May be outdated (page last edited before ${p.data?.gameVersion}): ${outdated.map((s: any) => s.title).join(", ")}.`);
  return L.join("\n");
}

/** One line for character_sync: where the synced character stands and the next 3 steps. */
export async function levellingSyncLine(pob: Pob): Promise<string | undefined> {
  try {
    const p = await levellingPlan(pob, {});
    if (!p?.ok || p.me.level >= 90) return undefined;
    const steps = (p.next ?? []).slice(0, 3).map((s: any) => s.text).join(" | ");
    return `LEVELLING: level ${p.me.level} in ${actName(p.me.act)}${steps ? ` - next: ${steps}` : ""}.`;
  } catch {
    return undefined;
  }
}
